using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using OneWay.Battle3D;
public static class ConnectNewPlayerLocomotion
{
 const string Folder="Assets/3DBattle/NewPlayer/PlayableAttacks";
 static float Floor(SkinnedMeshRenderer r){var m=r.sharedMesh;var v=m.vertices;var w=m.boneWeights;var matrices=r.bones.Select((b,i)=>b.localToWorldMatrix*m.bindposes[i]).ToArray();float y=float.MaxValue;for(int i=0;i<v.Length;i++){var a=w[i];var p=matrices[a.boneIndex0].MultiplyPoint3x4(v[i])*a.weight0+matrices[a.boneIndex1].MultiplyPoint3x4(v[i])*a.weight1+matrices[a.boneIndex2].MultiplyPoint3x4(v[i])*a.weight2+matrices[a.boneIndex3].MultiplyPoint3x4(v[i])*a.weight3;y=Mathf.Min(y,p.y);}return y;}
 public static object Run(){if(Application.isPlaying)throw new Exception("Stop play mode");var live=GameObject.Find("New Player - Attack Combo");if(live==null)throw new Exception("New player missing");foreach(var w in Resources.FindObjectsOfTypeAll<AnimationWindow>()){w.recording=false;w.previewing=false;}if(AnimationMode.InAnimationMode())AnimationMode.StopAnimationMode();var player=live.GetComponent<BattlePlayerController>();var combo=live.GetComponent<NewPlayerAttackCombo>();var controller=(AnimatorController)player.animator.runtimeAnimatorController;string[] previews={"Running Knight Preview","New Knight Roll Preview","New Knight Parry Preview"};string[] names={"NewPlayer_Run","NewPlayer_Roll","NewPlayer_Parry"};var outputs=new List<AnimationClip>();var reports=new List<object>();var temp=UnityEngine.Object.Instantiate(live.transform.Find("NewPlayer Visual").gameObject);temp.hideFlags=HideFlags.HideAndDontSave;temp.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var a=temp.GetComponentInChildren<Animator>();a.enabled=false;var paths=AnimationUtility.GetCurveBindings(combo.motions.idle).Select(b=>b.path).Distinct().OrderBy(p=>p.Count(c=>c=='/')).ToArray();var nodes=paths.Select(p=>a.transform.Find(p)).ToArray();var hip=nodes.First(t=>t.name=="Hips");combo.motions.idle.SampleAnimation(a.gameObject,0);Vector3 idleHip=hip.position;var errors=new List<string>();Application.LogCallback log=(m,s,t)=>{if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m);};Application.logMessageReceived+=log;
 try{for(int index=0;index<3;index++){
  var source=UnityEngine.Object.Instantiate(GameObject.Find(previews[index]));source.hideFlags=HideFlags.HideAndDontSave;source.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);try{var sa=source.GetComponentInChildren<Animator>();sa.enabled=false;var clip=sa.runtimeAnimatorController.animationClips[0];var sn=paths.Select(p=>sa.transform.Find(p)).ToArray();var sh=source.GetComponentsInChildren<Transform>().First(t=>t.name=="Hips");var records=paths.Select(_=>Enumerable.Range(0,10).Select(c=>new List<Keyframe>()).ToArray()).ToArray();int samples=Mathf.RoundToInt(clip.length*60);Quaternion[] previous=new Quaternion[nodes.Length];float minGround=float.MaxValue,maxOffset=0;
   for(int f=0;f<=samples;f++){float time=clip.length*f/samples;clip.SampleAnimation(sa.gameObject,time);combo.motions.idle.SampleAnimation(a.gameObject,0);for(int n=0;n<nodes.Length;n++)if(sn[n]!=null){nodes[n].localPosition=sn[n].localPosition;nodes[n].localRotation=sn[n].localRotation;nodes[n].localScale=sn[n].localScale;}
    // Same skeleton; absorb the preview's Armature parent into Hips without changing the live rig.
    hip.SetPositionAndRotation(sh.position,sh.rotation);hip.position=new Vector3(idleHip.x,hip.position.y,idleHip.z);float floor=Floor(temp.GetComponentInChildren<SkinnedMeshRenderer>());float lift=Mathf.Max(0,.015f-floor);hip.position+=Vector3.up*lift;minGround=Mathf.Min(minGround,floor+lift);maxOffset=Mathf.Max(maxOffset,lift);
    for(int n=0;n<nodes.Length;n++){var t=nodes[n];var q=t.localRotation;if(f>0&&Quaternion.Dot(previous[n],q)<0)q=new Quaternion(-q.x,-q.y,-q.z,-q.w);previous[n]=q;for(int c=0;c<10;c++)records[n][c].Add(new Keyframe(time,c<3?t.localPosition[c]:c<7?q[c-3]:t.localScale[c-7]));}
   }
   var output=new AnimationClip{name=names[index],frameRate=30};var bindings=new List<EditorCurveBinding>();var curves=new List<AnimationCurve>();for(int n=0;n<paths.Length;n++)for(int c=0;c<10;c++){var curve=new AnimationCurve(records[n][c].ToArray());for(int k=0;k<curve.length;k++){AnimationUtility.SetKeyLeftTangentMode(curve,k,AnimationUtility.TangentMode.Linear);AnimationUtility.SetKeyRightTangentMode(curve,k,AnimationUtility.TangentMode.Linear);}bindings.Add(EditorCurveBinding.FloatCurve(paths[n],typeof(Transform),c<3?"m_LocalPosition."+"xyz"[c]:c<7?"m_LocalRotation."+"xyzw"[c-3]:"m_LocalScale."+"xyz"[c-7]));curves.Add(curve);}AnimationUtility.SetEditorCurves(output,bindings.ToArray(),curves.ToArray());var settings=AnimationUtility.GetAnimationClipSettings(output);settings.loopTime=index==0;AnimationUtility.SetAnimationClipSettings(output,settings);if(errors.Count>0)throw new Exception(string.Join("|",errors));AssetDatabase.CreateAsset(output,AssetDatabase.GenerateUniqueAssetPath(Folder+"/"+names[index]+".anim"));var state=controller.layers[0].stateMachine.states.FirstOrDefault(s=>s.state.name==names[index]).state;if(state==null)state=controller.layers[0].stateMachine.AddState(names[index]);state.motion=output;outputs.Add(output);reports.Add(new{preview=previews[index],source=AssetDatabase.GetAssetPath(clip),frames=clip.length*30,minGround,maxGroundLift=maxOffset});
  }finally{UnityEngine.Object.DestroyImmediate(source);}
 }
 var parry=GameObject.Find("New Knight Parry Preview");var sourceShield=parry.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Shield4");var parentPath=AnimationUtility.CalculateTransformPath(sourceShield.parent,parry.GetComponentInChildren<Animator>().transform);var hand=player.animator.transform.Find(parentPath);if(hand==null)throw new Exception("Left hand missing");var old=hand.Find("Shield4");if(old!=null)throw new Exception("Shield already exists");var shield=UnityEngine.Object.Instantiate(sourceShield.gameObject,hand);shield.name="Shield4";shield.transform.localPosition=sourceShield.localPosition;shield.transform.localRotation=sourceShield.localRotation;shield.transform.localScale=sourceShield.localScale;player.shield=shield;shield.SetActive(false);var effect=live.GetComponent<BattleParryEffect>();effect.enabled=true;effect.shield=shield.transform;var movement=live.GetComponent<NewPlayerLocomotion>();if(movement==null)movement=live.AddComponent<NewPlayerLocomotion>();movement.runClip=outputs[0];movement.rollClip=outputs[1];movement.parryClip=outputs[2];combo.motions.idle.SampleAnimation(player.animator.gameObject,0);EditorUtility.SetDirty(controller);EditorUtility.SetDirty(player);EditorUtility.SetDirty(effect);EditorUtility.SetDirty(movement);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(live.scene);EditorSceneManager.SaveScene(live.scene);return new{motions=reports,shieldScale=shield.transform.localScale.ToString(),shieldWorldScaleError=Vector3.Distance(shield.transform.lossyScale,sourceShield.lossyScale),sameShieldPosition=shield.transform.localPosition==sourceShield.localPosition,sameShieldRotation=Quaternion.Angle(shield.transform.localRotation,sourceShield.localRotation),errors};
 }finally{Application.logMessageReceived-=log;UnityEngine.Object.DestroyImmediate(temp);}
 }
}
